const enc = new TextEncoder();
const hex = (buf) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');
async function sha256(texto) { return hex(await crypto.subtle.digest('SHA-256', enc.encode(texto))); }
async function hmac(secreto, mensaje) {
  const clave = await crypto.subtle.importKey('raw', enc.encode(secreto), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return hex(await crypto.subtle.sign('HMAC', clave, enc.encode(mensaje)));
}
const secreto = 'demo_secreto_hmac_NO_REAL';
const cuerpo = '{"destino":"Rosario","bultos":3}';
const ts = '1794600629';
const canonico = ['POST', '/v1/pedidos', ts, await sha256(cuerpo)].join('\n');
console.log(canonico);
console.log('firma:', await hmac(secreto, canonico));

// El mismo pedido con un bulto más: la firma cambia por completo.
const otro = ['POST', '/v1/pedidos', ts, await sha256('{"destino":"Rosario","bultos":4}')].join('\n');
console.log('con 4 bultos:', await hmac(secreto, otro));
